import { backendClient } from './client'

export const actionsService = {
  async activateApp(tenantId: string, appId: string): Promise<void> {
    await backendClient.fetch('/actions/app/activate', {
      method: 'POST',
      body: JSON.stringify({ tenantId, appId }),
    })
  },

  async activateTemplate(projectId: string, templateId: string): Promise<void> {
    await backendClient.fetch('/actions/template/activate', {
      method: 'POST',
      body: JSON.stringify({ projectId, templateId }),
    })
  },

  async sendTestNotification(userId: string, category: string): Promise<void> {
    await backendClient.fetch('/actions/notification/test', {
      method: 'POST',
      body: JSON.stringify({ userId, category }),
    })
  },
}
